/* Atum Kit v0.1 — the one token and component layer for desktop and web.
 * GENERATED by packages/atum-kit/scripts/build.mjs from tokens.json + components.css. Do not edit.
 * The phone mirrors these values in SwiftUI (AtumKit.swift) from dist/atum-kit-tokens.json.
 * Rules:
 *  - Actions are capsules; inputs and containers are rounded rectangles.
 *  - Nested corners are concentric: inner radius = outer radius - padding.
 *  - Colour is rare. Ink carries everything. Red marks danger, failures and mentions;
 *    amber marks a warning, on its icon only. No green, no tinted panels.
 *    Brand colour lives only inside app icons and the user's own content.
 *  - Glass is frosted, for floating chrome only (bars, menus, popovers, toasts). Content stays opaque.
 *  - Focus rings appear for keyboard focus only (:focus-visible).
 *  - The cursor stays an arrow on controls (Mac convention); links in text get the hand.
 * Theme scope: light on :root and .ak-light; dark on .ak-dark and on the desktop's .dark root.
 * color-scheme is set only by the explicit .ak-light / .ak-dark classes, never on bare :root,
 * so the desktop's own color-scheme (set inline by applyTheme) is left alone.
 */
/* ---------- Tokens (generated from tokens.json) ---------- */
:root, .ak-light {
  --ak-ground: #f4f5f7;
  --ak-chrome: #eceef1;
  --ak-surface: #ffffff;
  --ak-raised: #ffffff;
  --ak-sunk: #ebedf0;
  --ak-ink: #1b1d22;
  --ak-ink-2: #3b3f47;
  --ak-ink-3: #5f646d;
  --ak-ink-4: #8a8f98; /* Icons and strokes only, never text. */
  --ak-on-ink: #ffffff;
  --ak-bubble-own: #1b1d22; /* Your own chat bubble. Ink in light; a raised grey in dark, so it never glares (2026-10-28). */
  --ak-bubble-own-hover: #2c2f36;
  --ak-on-bubble-own: #ffffff;
  --ak-line: rgba(23, 25, 31, .08);
  --ak-line-2: rgba(23, 25, 31, .14);
  --ak-fill-quiet: rgba(23, 25, 31, .055);
  --ak-fill-hover: rgba(23, 25, 31, .05);
  --ak-fill-press: rgba(23, 25, 31, .10);
  --ak-fill-selected: rgba(23, 25, 31, .085);
  --ak-ink-hover: #2c2f36;
  --ak-ink-press: #3a3e46;
  --ak-danger: #b42318;
  --ak-danger-fill: rgba(180, 35, 24, .08);
  --ak-danger-hover: #9c1d14;
  --ak-warn: #9a5800;
  --ak-warn-fill: rgba(181, 106, 8, .10);
  --ak-ok: #1e7a35;
  --ak-ok-fill: rgba(36, 138, 61, .10);
  --ak-glass: rgba(255, 255, 255, .66);
  --ak-glass-rim: rgba(255, 255, 255, .75);
  --ak-glass-edge: rgba(23, 25, 31, .09);
  --ak-scrim: rgba(15, 16, 20, .26);
  --ak-shadow-1: 0 0 0 .5px rgba(15, 16, 20, .08), 0 1px 2px rgba(15, 16, 20, .05);
  --ak-shadow-2: 0 12px 32px -10px rgba(15, 16, 20, .20), 0 2px 6px rgba(15, 16, 20, .06);
  --ak-shadow-3: 0 32px 80px -24px rgba(15, 16, 20, .36), 0 8px 20px rgba(15, 16, 20, .08);
  --ak-focus: rgba(27, 29, 34, .42);
  --ak-knob: #ffffff;
  --ak-monogram: linear-gradient(180deg, #a9adb5, #868a93);
  --ak-frame: rgba(232, 234, 238, .62); /* Window frame over macOS vibrancy: rail + title bar. */
  --ak-panel: rgba(255, 255, 255, .58); /* Roster panel: lighter frosted layer. */
  --ak-panel-rim: rgba(255, 255, 255, .7);
}
.ak-dark, .dark {
  --ak-ground: #17181c;
  --ak-chrome: #111215;
  --ak-surface: #1f2025;
  --ak-raised: #26272c;
  --ak-sunk: #2a2b31;
  --ak-ink: #ecedf0;
  --ak-ink-2: #c9ccd2;
  --ak-ink-3: #9da2ab;
  --ak-ink-4: #6e737c; /* Icons and strokes only, never text. */
  --ak-on-ink: #17181c;
  --ak-bubble-own: #3d3f47; /* Your own chat bubble. Ink in light; a raised grey in dark, so it never glares (2026-10-28). */
  --ak-bubble-own-hover: #464851;
  --ak-on-bubble-own: #f4f5f7;
  --ak-line: rgba(255, 255, 255, .08);
  --ak-line-2: rgba(255, 255, 255, .14);
  --ak-fill-quiet: rgba(255, 255, 255, .065);
  --ak-fill-hover: rgba(255, 255, 255, .06);
  --ak-fill-press: rgba(255, 255, 255, .11);
  --ak-fill-selected: rgba(255, 255, 255, .095);
  --ak-ink-hover: #ffffff;
  --ak-ink-press: #d6d8dd;
  --ak-danger: #f0716a;
  --ak-danger-fill: rgba(240, 113, 106, .13);
  --ak-danger-hover: #ff8a83;
  --ak-warn: #f0a93b;
  --ak-warn-fill: rgba(240, 169, 59, .13);
  --ak-ok: #3dd068;
  --ak-ok-fill: rgba(61, 208, 104, .13);
  --ak-glass: rgba(42, 43, 49, .64);
  --ak-glass-rim: rgba(255, 255, 255, .10);
  --ak-glass-edge: rgba(0, 0, 0, .45);
  --ak-scrim: rgba(0, 0, 0, .46);
  --ak-shadow-1: 0 0 0 .5px rgba(255, 255, 255, .07), 0 1px 2px rgba(0, 0, 0, .3);
  --ak-shadow-2: 0 14px 36px -10px rgba(0, 0, 0, .55), 0 2px 6px rgba(0, 0, 0, .3);
  --ak-shadow-3: 0 36px 90px -24px rgba(0, 0, 0, .7), 0 8px 20px rgba(0, 0, 0, .35);
  --ak-focus: rgba(236, 237, 240, .5);
  --ak-knob: #f4f5f7;
  --ak-monogram: linear-gradient(180deg, #74787f, #55585e);
  --ak-frame: rgba(22, 23, 27, .58); /* Window frame over macOS vibrancy: rail + title bar. */
  --ak-panel: rgba(255, 255, 255, .045); /* Roster panel: lighter frosted layer. */
  --ak-panel-rim: rgba(255, 255, 255, .07);
}
:root, .ak-light, .ak-dark {
  --ak-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", system-ui, sans-serif;
  --ak-font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", system-ui, sans-serif;
  --ak-font-mono: "SF Mono", ui-monospace, "JetBrains Mono", Menlo, monospace;
  --ak-t-display: 600 26px/32px var(--ak-font-display);
  --ak-t-title: 600 20px/26px var(--ak-font-display);
  --ak-t-headline: 600 15px/20px var(--ak-font);
  --ak-t-chat: 400 15px/23px var(--ak-font);
  --ak-t-body: 400 13px/18px var(--ak-font);
  --ak-t-body-strong: 600 13px/18px var(--ak-font);
  --ak-t-callout: 400 12px/16px var(--ak-font);
  --ak-t-caption: 500 11px/14px var(--ak-font);
  --ak-s1: 4px;
  --ak-s2: 8px;
  --ak-s3: 12px;
  --ak-s4: 16px;
  --ak-s5: 20px;
  --ak-s6: 24px;
  --ak-s8: 32px;
  --ak-s12: 48px;
  --ak-r-xs: 6px;
  --ak-r-sm: 8px;
  --ak-r-md: 10px;
  --ak-r-lg: 14px;
  --ak-r-xl: 20px;
  --ak-r-2xl: 26px;
  --ak-r-full: 999px;
  --ak-h-sm: 26px;
  --ak-h-md: 32px;
  --ak-h-lg: 40px;
  --ak-i-sm: 16px;
  --ak-i-md: 18px;
  --ak-i-lg: 20px;
  --ak-i-xl: 24px;
  --ak-ease: cubic-bezier(.32, .72, 0, 1);
  --ak-ease-in: cubic-bezier(.4, 0, 1, 1);
  --ak-dur-1: 120ms;
  --ak-dur-2: 200ms;
  --ak-dur-3: 320ms;
  --ak-blur: blur(24px) saturate(170%);
}
.ak-light { color-scheme: light; }
.ak-dark { color-scheme: dark; }

/* ---------- Components (components.css) ---------- */
/* Atum Kit 0.1 components. Hand-maintained; tokens come from tokens.json.
 * scripts/build.mjs prepends the generated token blocks to make dist/atum-kit.css.
 * Rules (see the header of dist/atum-kit.css): capsule actions, rounded-rect inputs,
 * concentric corners, rare colour, glass for floating chrome only, keyboard-only
 * focus rings, arrow cursor on controls, circles for people, squircles for apps.
 * Every class is ak- prefixed and every variable --ak-, so loading this file
 * changes nothing until a surface opts in.
 */

.ak-light, .ak-dark { color: var(--ak-ink); font: var(--ak-t-body); -webkit-font-smoothing: antialiased; }

/* ---------- Base ---------- */
.ak-icon { width: var(--ak-i-md); height: var(--ak-i-md); flex: none; fill: currentColor; }
.ak-icon--sm { width: var(--ak-i-sm); height: var(--ak-i-sm); }
.ak-icon--lg { width: var(--ak-i-lg); height: var(--ak-i-lg); }
.ak-icon--xl { width: var(--ak-i-xl); height: var(--ak-i-xl); }
.ak-focusable:focus-visible, .ak-btn:focus-visible, .ak-iconbtn:focus-visible, .ak-field:focus-within, .ak-btn.is-focus, .ak-iconbtn.is-focus, .ak-field.is-focus {
  outline: 3px solid var(--ak-focus); outline-offset: 1px;
}
.ak-glass {
  background: var(--ak-glass);
  -webkit-backdrop-filter: var(--ak-blur); backdrop-filter: var(--ak-blur);
  box-shadow: inset 0 0 0 .5px var(--ak-glass-edge), inset 0 1px 0 var(--ak-glass-rim), var(--ak-shadow-2);
}
@media (prefers-reduced-transparency: reduce) {
  .ak-glass { background: var(--ak-raised); -webkit-backdrop-filter: none; backdrop-filter: none; }
}
.ak-text-2 { color: var(--ak-ink-2); } .ak-text-3 { color: var(--ak-ink-3); }

/* ---------- Buttons (capsules) ---------- */
.ak-btn {
  appearance: none; border: 0; margin: 0; cursor: default; user-select: none;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: var(--ak-h-md); padding: 0 14px; border-radius: var(--ak-r-full);
  font: var(--ak-t-body-strong); white-space: nowrap;
  background: var(--ak-fill-quiet); color: var(--ak-ink);
  transition: background-color var(--ak-dur-1) var(--ak-ease), color var(--ak-dur-1) var(--ak-ease), transform var(--ak-dur-1) var(--ak-ease);
}
.ak-btn .ak-icon { width: 16px; height: 16px; margin-left: -2px; }
.ak-btn:hover, .ak-btn.is-hover { background: var(--ak-fill-press); }
.ak-btn:active, .ak-btn.is-press { background: var(--ak-fill-press); transform: scale(.98); }
.ak-btn--primary { background: var(--ak-ink); color: var(--ak-on-ink); }
.ak-btn--primary:hover, .ak-btn--primary.is-hover { background: var(--ak-ink-hover); }
.ak-btn--primary:active, .ak-btn--primary.is-press { background: var(--ak-ink-press); }
.ak-btn--plain { background: transparent; }
.ak-btn--plain:hover, .ak-btn--plain.is-hover { background: var(--ak-fill-hover); }
.ak-btn--plain:active, .ak-btn--plain.is-press { background: var(--ak-fill-press); }
.ak-btn--danger { background: var(--ak-fill-quiet); color: var(--ak-danger); }
.ak-btn--danger:hover, .ak-btn--danger.is-hover { color: var(--ak-danger-hover); }
.ak-btn--danger-solid { background: var(--ak-danger); color: #fff; }
.ak-btn--glass { background: var(--ak-glass); -webkit-backdrop-filter: var(--ak-blur); backdrop-filter: var(--ak-blur); box-shadow: inset 0 0 0 .5px var(--ak-glass-edge), inset 0 1px 0 var(--ak-glass-rim), var(--ak-shadow-1); }
.ak-btn--sm { height: var(--ak-h-sm); padding: 0 11px; font: var(--ak-t-callout); font-weight: 600; }
.ak-btn--lg { height: var(--ak-h-lg); padding: 0 18px; font-size: 14px; }
.ak-btn:disabled, .ak-btn.is-disabled { opacity: .38; transform: none; pointer-events: none; }

.ak-iconbtn {
  appearance: none; border: 0; margin: 0; padding: 0; cursor: default;
  width: var(--ak-h-md); height: var(--ak-h-md); border-radius: var(--ak-r-full);
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; color: var(--ak-ink-2);
  transition: background-color var(--ak-dur-1) var(--ak-ease), color var(--ak-dur-1) var(--ak-ease);
}
.ak-iconbtn:hover, .ak-iconbtn.is-hover { background: var(--ak-fill-hover); color: var(--ak-ink); }
.ak-iconbtn:active, .ak-iconbtn.is-press { background: var(--ak-fill-press); color: var(--ak-ink); }
.ak-iconbtn--sm { width: var(--ak-h-sm); height: var(--ak-h-sm); }
.ak-iconbtn--glass { background: var(--ak-glass); -webkit-backdrop-filter: var(--ak-blur); backdrop-filter: var(--ak-blur); box-shadow: inset 0 0 0 .5px var(--ak-glass-edge), inset 0 1px 0 var(--ak-glass-rim), var(--ak-shadow-1); color: var(--ak-ink); }
.ak-iconbtn--primary { background: var(--ak-ink); color: var(--ak-on-ink); }
.ak-iconbtn--primary:hover, .ak-iconbtn--primary.is-hover { background: var(--ak-ink-hover); color: var(--ak-on-ink); }

/* ---------- Inputs (rounded rectangles) ---------- */
.ak-field {
  display: flex; align-items: center; gap: 8px; height: var(--ak-h-md); padding: 0 10px;
  border-radius: var(--ak-r-md); background: var(--ak-surface);
  box-shadow: inset 0 0 0 1px var(--ak-line-2);
  transition: box-shadow var(--ak-dur-1) var(--ak-ease);
}
.ak-field input, .ak-field textarea { all: unset; flex: 1; min-width: 0; font: var(--ak-t-body); color: var(--ak-ink); }
.ak-field .ak-placeholder, .ak-field input::placeholder { color: var(--ak-ink-3); }
.ak-field--error { box-shadow: inset 0 0 0 1px var(--ak-danger); }
.ak-field--search { border-radius: var(--ak-r-full); background: var(--ak-fill-quiet); box-shadow: none; color: var(--ak-ink-3); }
.ak-field-label { font: var(--ak-t-body-strong); color: var(--ak-ink); margin-bottom: 6px; display: block; }
.ak-field-help { font: var(--ak-t-callout); color: var(--ak-ink-3); margin-top: 6px; }
.ak-field-help--error { color: var(--ak-danger); }

.ak-select {
  appearance: none; border: 0; cursor: default;
  display: inline-flex; align-items: center; justify-content: space-between; gap: 10px;
  height: var(--ak-h-md); padding: 0 8px 0 11px; border-radius: var(--ak-r-md);
  background: var(--ak-surface); box-shadow: inset 0 0 0 1px var(--ak-line-2), var(--ak-shadow-1);
  font: var(--ak-t-body); color: var(--ak-ink);
}
.ak-select .ak-icon { width: 14px; height: 14px; color: var(--ak-ink-3); }

.ak-switch { position: relative; width: 38px; height: 22px; border-radius: var(--ak-r-full); background: var(--ak-line-2); flex: none; transition: background-color var(--ak-dur-2) var(--ak-ease); }
.ak-switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 18px; height: 18px; border-radius: 50%; background: var(--ak-knob); box-shadow: 0 1px 3px rgba(0,0,0,.22), 0 0 0 .5px rgba(0,0,0,.06); transition: transform var(--ak-dur-2) var(--ak-ease); }
.ak-switch.is-on { background: var(--ak-ink); }
.ak-switch.is-on::after { transform: translateX(16px); }
.ak-dark .ak-switch.is-on::after, .dark .ak-switch.is-on::after { background: var(--ak-on-ink); }

.ak-check { width: 16px; height: 16px; border-radius: 5px; box-shadow: inset 0 0 0 1px var(--ak-line-2); background: var(--ak-surface); display: inline-flex; align-items: center; justify-content: center; flex: none; color: var(--ak-on-ink); }
.ak-check.is-on { background: var(--ak-ink); box-shadow: none; }
.ak-check .ak-icon { width: 12px; height: 12px; }
.ak-radio { width: 16px; height: 16px; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--ak-line-2); background: var(--ak-surface); flex: none; }
.ak-radio.is-on { box-shadow: inset 0 0 0 5px var(--ak-ink); }

.ak-seg { display: inline-flex; padding: 2px; border-radius: var(--ak-r-full); background: var(--ak-fill-quiet); gap: 2px; }
.ak-seg > * { appearance: none; border: 0; cursor: default; height: 26px; padding: 0 12px; border-radius: var(--ak-r-full); background: transparent; font: var(--ak-t-body); color: var(--ak-ink-2); display: inline-flex; align-items: center; gap: 6px; }
.ak-seg > .is-selected { background: var(--ak-surface); color: var(--ak-ink); font-weight: 600; box-shadow: var(--ak-shadow-1); }
.ak-dark .ak-seg > .is-selected, .dark .ak-seg > .is-selected { background: var(--ak-raised); }

/* ---------- Lists ---------- */
.ak-group { background: var(--ak-surface); border-radius: var(--ak-r-lg); padding: 4px; box-shadow: var(--ak-shadow-1); display: flex; flex-direction: column; }
.ak-row { display: flex; align-items: center; gap: 10px; min-height: 36px; padding: 6px 10px; border-radius: var(--ak-r-md); color: var(--ak-ink); font: var(--ak-t-body); position: relative; }
.ak-row:hover, .ak-row.is-hover { background: var(--ak-fill-hover); }
.ak-row.is-selected { background: var(--ak-fill-selected); font-weight: 600; }
.ak-row .ak-icon { color: var(--ak-ink-2); }
.ak-row-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.ak-row-meta { font: var(--ak-t-callout); color: var(--ak-ink-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ak-row + .ak-row::before { content: ""; position: absolute; top: 0; left: 40px; right: 10px; height: 1px; background: var(--ak-line); }
.ak-group--plain .ak-row + .ak-row::before { display: none; }
.ak-section { font: var(--ak-t-caption); font-weight: 600; color: var(--ak-ink-3); padding: 12px 10px 4px; }

.ak-badge { min-width: 18px; height: 18px; padding: 0 5px; border-radius: var(--ak-r-full); background: var(--ak-ink); color: var(--ak-on-ink); font: 600 11px/18px var(--ak-font); text-align: center; font-variant-numeric: tabular-nums; }
.ak-badge--mention { background: var(--ak-danger); color: #fff; }
.ak-badge--quiet { background: var(--ak-fill-press); color: var(--ak-ink-2); }
.ak-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ak-ink); }

.ak-avatar { width: 28px; height: 28px; border-radius: 50%; flex: none; display: inline-flex; align-items: center; justify-content: center; font: 600 12px/1 var(--ak-font); color: #fff; overflow: hidden; background: var(--ak-monogram); letter-spacing: .02em; }
.ak-avatar--sm { width: 20px; height: 20px; font-size: 10px; }
.ak-avatar--lg { width: 40px; height: 40px; font-size: 15px; }

/* ---------- Overlays ---------- */
.ak-menu { min-width: 220px; padding: 6px; border-radius: var(--ak-r-lg); display: flex; flex-direction: column; }
.ak-menu-item { display: flex; align-items: center; gap: 10px; height: 28px; padding: 0 8px 0 10px; border-radius: var(--ak-r-sm); font: var(--ak-t-body); color: var(--ak-ink); cursor: default; }
.ak-menu-item .ak-icon { width: 16px; height: 16px; color: var(--ak-ink-2); }
.ak-menu-item:hover, .ak-menu-item.is-hover { background: var(--ak-fill-selected); }
.ak-menu-item--danger, .ak-menu-item--danger .ak-icon { color: var(--ak-danger); }
.ak-menu-key { margin-left: auto; font: var(--ak-t-callout); color: var(--ak-ink-3); letter-spacing: .04em; }
.ak-menu-sep { height: 1px; background: var(--ak-line); margin: 5px 10px; }
.ak-menu-label { font: var(--ak-t-caption); font-weight: 600; color: var(--ak-ink-3); padding: 6px 10px 3px; }

.ak-popover { padding: 16px; border-radius: var(--ak-r-xl); display: flex; flex-direction: column; gap: 12px; }
.ak-tooltip { display: inline-flex; padding: 5px 9px; border-radius: var(--ak-r-sm); background: var(--ak-ink); color: var(--ak-on-ink); font: var(--ak-t-callout); font-weight: 500; box-shadow: var(--ak-shadow-2); }

.ak-scrim { background: var(--ak-scrim); }
.ak-dialog { width: 380px; padding: 22px; border-radius: var(--ak-r-2xl); background: var(--ak-raised); box-shadow: inset 0 0 0 .5px var(--ak-line-2), var(--ak-shadow-3); display: flex; flex-direction: column; gap: 8px; }
.ak-dialog-title { font: var(--ak-t-headline); color: var(--ak-ink); margin: 0; }
.ak-dialog-body { font: var(--ak-t-body); color: var(--ak-ink-2); margin: 0; }
.ak-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 14px; }
.ak-sheet { width: 560px; border-radius: var(--ak-r-2xl); background: var(--ak-raised); box-shadow: inset 0 0 0 .5px var(--ak-line-2), var(--ak-shadow-3); display: flex; flex-direction: column; overflow: hidden; }
.ak-sheet-head { display: flex; align-items: center; gap: 10px; padding: 16px 16px 4px 22px; }
.ak-sheet-title { font: var(--ak-t-title); flex: 1; margin: 0; letter-spacing: -.01em; }
.ak-sheet-body { padding: 8px 22px 16px; display: flex; flex-direction: column; gap: 14px; }
.ak-sheet-foot { display: flex; justify-content: flex-end; gap: 8px; padding: 14px 16px 16px; border-top: 1px solid var(--ak-line); }

.ak-toast { display: inline-flex; align-items: center; gap: 10px; height: 40px; padding: 0 6px 0 14px; border-radius: var(--ak-r-full); font: var(--ak-t-body); color: var(--ak-ink); }
.ak-toast .ak-icon { width: 18px; height: 18px; }

/* ---------- Feedback ---------- */
.ak-notice { display: flex; gap: 12px; align-items: flex-start; padding: 12px 12px 12px 14px; border-radius: var(--ak-r-lg); background: var(--ak-fill-quiet); }
.ak-notice > .ak-icon { width: 20px; height: 20px; margin-top: -1px; color: var(--ak-ink-2); }
.ak-notice-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ak-notice-title { font: var(--ak-t-body-strong); color: var(--ak-ink); }
.ak-notice-body { font: var(--ak-t-body); color: var(--ak-ink-2); }
.ak-notice-actions { display: flex; gap: 6px; flex: none; align-self: center; }
.ak-notice--warn > .ak-icon { color: var(--ak-warn); }
.ak-notice--danger > .ak-icon { color: var(--ak-danger); }

.ak-state { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 6px; padding: 28px 20px; }
.ak-state-mark { width: 52px; height: 52px; border-radius: 50%; background: var(--ak-fill-quiet); display: flex; align-items: center; justify-content: center; color: var(--ak-ink-2); margin-bottom: 8px; }
.ak-state-mark .ak-icon { width: 26px; height: 26px; }
.ak-state-title { font: var(--ak-t-headline); color: var(--ak-ink); }
.ak-state-body { font: var(--ak-t-body); color: var(--ak-ink-3); max-width: 34ch; }
.ak-state .ak-btn { margin-top: 10px; }

.ak-spinner { width: 16px; height: 16px; border-radius: 50%; border: 2px solid var(--ak-line-2); border-top-color: var(--ak-ink-2); animation: ak-spin 800ms linear infinite; flex: none; }
.ak-spinner--lg { width: 22px; height: 22px; }
@keyframes ak-spin { to { transform: rotate(360deg); } }
.ak-skeleton { border-radius: var(--ak-r-xs); background: var(--ak-fill-quiet); }
@media (prefers-reduced-motion: reduce) { .ak-spinner { animation-duration: 2400ms; } .ak-btn, .ak-switch::after { transition: none; } }

/* ---------- Atum asks ---------- */
.ak-ask { display: flex; flex-direction: column; gap: 12px; padding: 16px; border-radius: var(--ak-r-xl); background: var(--ak-surface); box-shadow: var(--ak-shadow-1); max-width: 460px; }
.ak-ask-head { display: flex; gap: 12px; align-items: flex-start; }
.ak-ask-mark { width: 32px; height: 32px; border-radius: 50%; flex: none; display: flex; align-items: center; justify-content: center; background: var(--ak-fill-quiet); color: var(--ak-ink); }
.ak-ask-mark .ak-icon { width: 18px; height: 18px; }
.ak-ask-title { font: var(--ak-t-headline); color: var(--ak-ink); }
.ak-ask-body { font: var(--ak-t-body); color: var(--ak-ink-2); margin-top: 2px; }
.ak-ask-list { display: flex; flex-direction: column; gap: 6px; padding-left: 44px; font: var(--ak-t-body); color: var(--ak-ink-2); }
.ak-ask-list > div { display: flex; gap: 8px; align-items: center; }
.ak-ask-list .ak-icon { width: 16px; height: 16px; color: var(--ak-ink-3); }
.ak-ask-actions { display: flex; gap: 8px; padding-left: 44px; }
.ak-ask-line { display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 12px 0 10px; border-radius: var(--ak-r-full); background: var(--ak-fill-quiet); font: var(--ak-t-body); color: var(--ak-ink-2); }
.ak-ask-line .ak-icon { width: 16px; height: 16px; }
.ak-ask-line--ok .ak-icon { color: var(--ak-ink); }

